import java.util.*;
import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) {
        SignalingServer signalingServer = new SignalingServer(); // the control plane

        WebSocketSession aliceSession = new WebSocketSession("alice");   // alice's signaling connection
        WebSocketSession bobSession = new WebSocketSession("bob");          // bob's signaling connection

        signalingServer.onParticipantConnect("meeting-1", "alice", aliceSession); // alice joins the meeting
        signalingServer.onParticipantConnect("meeting-1", "bob", bobSession);         // bob joins the same meeting

        SfuAssignment aliceAssignment = (SfuAssignment) aliceSession.getReceived().get(0); // what alice was told
        SfuAssignment bobAssignment = (SfuAssignment) bobSession.getReceived().get(0);         // what bob was told
