        System.out.println("Layer for 700 kbps: " + decider.chooseLayerFor(700));      // moderate bandwidth
        System.out.println("Layer for 200 kbps: " + decider.chooseLayerFor(200));        // weak bandwidth

        SimulcastForwardingDecider.Layer stableLayer = decider.reevaluate("carol", 2100, SimulcastForwardingDecider.Layer.HIGH);
        System.out.println("Reevaluating a stable, still-strong connection stays at: " + stableLayer);

        SimulcastForwardingDecider.Layer downgradedLayer = decider.reevaluate("carol", 300, SimulcastForwardingDecider.Layer.HIGH);
