// A tiny stand in for a real WebSocket connection, capturing every message
// actually sent to it so this demo can verify delivery.
class WebSocketSession {
    private final String participantId;                       // whose connection this is
    private final List<Object> received = new ArrayList<>();     // every message delivered so far

    public WebSocketSession(String participantId) {
        this.participantId = participantId; // store id
    }

    public void send(Object message) {
        received.add(message); // record whatever was sent, whether an SfuAssignment or a SignalingMessage
    }

    public List<Object> getReceived() { return received; } // full delivery history getter
}

// One SDP offer, answer, or ICE candidate being relayed between two clients.
class SignalingMessage {
    private final String type;      // "offer", "answer", or "ice-candidate"
    private final String payload;      // the actual SDP or candidate content

    public SignalingMessage(String type, String payload) {
        this.type = type;           // store the message kind
        this.payload = payload;        // store the payload
    }

    @Override
    public String toString() { return type + ": " + payload; } // readable form for printing
}

// Tells a joining client which SFU instance to connect its media to.
class SfuAssignment {
    private final String sfuId; // which SFU instance was assigned

    public SfuAssignment(String sfuId) {
        this.sfuId = sfuId; // store the assignment
    }

    public String getSfuId() { return sfuId; } // sfu id getter

    @Override
    public String toString() { return "SfuAssignment(" + sfuId + ")"; } // readable form for printing
}

// Relays SDP offers, answers, and ICE candidates between two clients
// setting up a connection to the same SFU. The signaling server never
// touches the actual media, only the handshake messages that precede it.
class SignalingServer {
    private final Map<String, WebSocketSession> sessionsByParticipant = new ConcurrentHashMap<>(); // participantId -> their connection
    private final Map<String, String> assignedSfuByMeeting = new ConcurrentHashMap<>();                // meetingId -> chosen SFU

    public void onParticipantConnect(String meetingId, String participantId, WebSocketSession session) {
        sessionsByParticipant.put(participantId, session);                                     // remember this participant's connection
        String sfuId = assignedSfuByMeeting.computeIfAbsent(meetingId, id -> pickNearestHealthySfu()); // reuse the meeting's SFU if already chosen
        session.send(new SfuAssignment(sfuId)); // tell the client which SFU to connect to
    }

    // Relays an SDP offer or answer, or an ICE candidate, without inspecting its contents.
    public void relaySignalingMessage(String fromParticipantId, String toParticipantId, SignalingMessage message) {
        WebSocketSession target = sessionsByParticipant.get(toParticipantId); // the intended recipient's connection
        if (target != null) {
            target.send(message); // forward it, untouched
        }
    }

    private String pickNearestHealthySfu() {
        // In a real system, this consults a service registry and client region.
        return "sfu-instance-1";
    }
}

// Runs on the SFU: decides, per recipient, which simulcast layer of a
// sender's video to actually forward, based on that recipient's current
// bandwidth estimate.
class SimulcastForwardingDecider {
    enum Layer { LOW, MEDIUM, HIGH }

    // Chooses the highest layer that still fits comfortably within the
    // recipient's estimated available bandwidth, leaving headroom so a
    // small fluctuation does not immediately force another switch.
    public Layer chooseLayerFor(double recipientBandwidthKbps) {
        double safetyMargin = 0.8;                            // only use 80 percent of estimated bandwidth
        double usable = recipientBandwidthKbps * safetyMargin;   // the bandwidth this decision actually relies on
        if (usable >= 1500) return Layer.HIGH;                      // plenty of headroom, send the best layer
        if (usable >= 500) return Layer.MEDIUM;                       // moderate headroom, send the middle layer
        return Layer.LOW;                                                // limited headroom, send the safest layer
    }

    // Called whenever a recipient's bandwidth estimate changes meaningfully,
    // for example after packet loss or jitter measurements shift.
    public Layer reevaluate(String recipientId, double newBandwidthKbps, Layer currentLayer) {
        Layer target = chooseLayerFor(newBandwidthKbps); // what the new bandwidth estimate calls for
        if (target == currentLayer) {
            return currentLayer; // no change needed, avoid unnecessary layer switches
        }
        return target; // switch, the SFU will begin forwarding this layer instead
    }
}

