// A message that can be either an SfuAssignment or a SignalingMessage, so a
// session's inbox can hold either kind, matching the Java Object-typed list.
struct InboxMessage {
    virtual std::string toString() const = 0;
    virtual ~InboxMessage() = default;
};

// One SDP offer, answer, or ICE candidate being relayed between two clients.
class SignalingMessage : public InboxMessage {
public:
    SignalingMessage(std::string type, std::string payload) : type_(std::move(type)), payload_(std::move(payload)) {}
    std::string toString() const override { return type_ + ": " + payload_; }

private:
    std::string type_;      // "offer", "answer", or "ice-candidate"
    std::string payload_;      // the actual SDP or candidate content
};

// Tells a joining client which SFU instance to connect its media to.
class SfuAssignment : public InboxMessage {
public:
    explicit SfuAssignment(std::string sfuId) : sfuId_(std::move(sfuId)) {}
    const std::string& getSfuId() const { return sfuId_; }
    std::string toString() const override { return "SfuAssignment(" + sfuId_ + ")"; }

private:
    std::string sfuId_;   // which SFU instance was assigned
};

// A tiny stand in for a real WebSocket connection, capturing every message
// actually sent to it so this demo can verify delivery.
class WebSocketSession {
public:
    explicit WebSocketSession(std::string participantId) : participantId_(std::move(participantId)) {}

    void send(std::shared_ptr<InboxMessage> message) {
        received_.push_back(message);   // record whatever was sent, whether an SfuAssignment or a SignalingMessage
    }
    const std::vector<std::shared_ptr<InboxMessage>>& getReceived() const { return received_; }

private:
    std::string participantId_;
    std::vector<std::shared_ptr<InboxMessage>> received_;
};

// Relays SDP offers, answers, and ICE candidates between two clients
// setting up a connection to the same SFU. The signaling server never
// touches the actual media, only the handshake messages that precede it.
class SignalingServer {
public:
    void onParticipantConnect(const std::string& meetingId, const std::string& participantId, WebSocketSession* session) {
        sessionsByParticipant_[participantId] = session;                    // remember this participant's connection
        if (assignedSfuByMeeting_.find(meetingId) == assignedSfuByMeeting_.end()) {   // reuse the meeting's SFU if already chosen
            assignedSfuByMeeting_[meetingId] = pickNearestHealthySfu();
        }
        session->send(std::make_shared<SfuAssignment>(assignedSfuByMeeting_[meetingId]));   // tell the client which SFU to connect to
    }

    // Relays an SDP offer or answer, or an ICE candidate, without inspecting its contents.
    void relaySignalingMessage(const std::string&, const std::string& toParticipantId, std::shared_ptr<SignalingMessage> message) {
        auto it = sessionsByParticipant_.find(toParticipantId);   // the intended recipient's connection
        if (it != sessionsByParticipant_.end()) {
            it->second->send(message);   // forward it, untouched
        }
    }

private:
    std::string pickNearestHealthySfu() {
        // In a real system, this consults a service registry and client region.
        return "sfu-instance-1";
    }

    std::map<std::string, WebSocketSession*> sessionsByParticipant_;
    std::map<std::string, std::string> assignedSfuByMeeting_;
};

enum class Layer { LOW, MEDIUM, HIGH };

std::string layerName(Layer l) {
    switch (l) { case Layer::LOW: return "LOW"; case Layer::MEDIUM: return "MEDIUM"; case Layer::HIGH: return "HIGH"; }
    return "?";
}

// Runs on the SFU: decides, per recipient, which simulcast layer of a
// sender's video to actually forward, based on that recipient's current
// bandwidth estimate.
class SimulcastForwardingDecider {
public:
    // Chooses the highest layer that still fits comfortably within the
    // recipient's estimated available bandwidth, leaving headroom so a
    // small fluctuation does not immediately force another switch.
    Layer chooseLayerFor(double recipientBandwidthKbps) {
        double safetyMargin = 0.8;                              // only use 80 percent of estimated bandwidth
        double usable = recipientBandwidthKbps * safetyMargin;     // the bandwidth this decision actually relies on
        if (usable >= 1500) return Layer::HIGH;                        // plenty of headroom, send the best layer
        if (usable >= 500) return Layer::MEDIUM;                         // moderate headroom, send the middle layer
        return Layer::LOW;                                                  // limited headroom, send the safest layer
    }

    // Called whenever a recipient's bandwidth estimate changes meaningfully,
    // for example after packet loss or jitter measurements shift.
    Layer reevaluate(const std::string&, double newBandwidthKbps, Layer currentLayer) {
        Layer target = chooseLayerFor(newBandwidthKbps);   // what the new bandwidth estimate calls for
        if (target == currentLayer) return currentLayer;      // no change needed, avoid unnecessary layer switches
        return target;                                            // switch, the SFU will begin forwarding this layer instead
    }
};

int main() {
    std::cout << std::boolalpha;
    SignalingServer signalingServer;   // the control plane

    WebSocketSession aliceSession("alice");   // alice's signaling connection
    WebSocketSession bobSession("bob");          // bob's signaling connection

    signalingServer.onParticipantConnect("meeting-1", "alice", &aliceSession);   // alice joins the meeting
    signalingServer.onParticipantConnect("meeting-1", "bob", &bobSession);          // bob joins the same meeting

    auto aliceAssignment = std::static_pointer_cast<SfuAssignment>(aliceSession.getReceived()[0]);   // what alice was told
    auto bobAssignment = std::static_pointer_cast<SfuAssignment>(bobSession.getReceived()[0]);          // what bob was told
    std::cout << "Alice assigned to: " << aliceAssignment->getSfuId() << "\n";
    std::cout << "Bob assigned to: " << bobAssignment->getSfuId() << "\n";
    std::cout << "Both participants share the same SFU: " << (aliceAssignment->getSfuId() == bobAssignment->getSfuId()) << "\n";

    // Alice sends an SDP offer to Bob, relayed untouched by the signaling server.
    signalingServer.relaySignalingMessage("alice", "bob", std::make_shared<SignalingMessage>("offer", "v=0 o=alice ..."));
    std::cout << "Messages Bob received: " << bobSession.getReceived().size() << "\n";   // the SFU assignment, plus the relayed offer
    std::cout << "Bob's latest message: " << bobSession.getReceived().back()->toString() << "\n";

    // Now demonstrate the SFU's simulcast layer decisions for a few different bandwidth estimates.
    SimulcastForwardingDecider decider;
    std::cout << "Layer for 2000 kbps: " << layerName(decider.chooseLayerFor(2000)) << "\n";   // plenty of bandwidth
    std::cout << "Layer for 700 kbps: " << layerName(decider.chooseLayerFor(700)) << "\n";        // moderate bandwidth
    std::cout << "Layer for 200 kbps: " << layerName(decider.chooseLayerFor(200)) << "\n";           // weak bandwidth

    Layer stableLayer = decider.reevaluate("carol", 2100, Layer::HIGH);
    std::cout << "Reevaluating a stable, still-strong connection stays at: " << layerName(stableLayer) << "\n";

    Layer downgradedLayer = decider.reevaluate("carol", 300, Layer::HIGH);
    std::cout << "Reevaluating after bandwidth drops downgrades to: " << layerName(downgradedLayer) << "\n";
    return 0;
}

